struct Resource { int id; };

// 1. Preferred creation (exception safe, single allocation)
auto p1 = std::make_shared<Resource>(42);

// 2. Access
p1->id = 100;
int val = (*p1).id;

// 3. Shared ownership via copy
std::shared_ptr<Resource> p2 = p1;

// 4. Reference count tracking
// Returns 2
size_t count = p1.use_count();

// 5. Explicitly release ownership
p2.reset();

// 6. Access raw pointer (use sparingly)
Resource* raw = p1.get();

// When p1 goes out of scope, the Resource is deleted.
